import {
  Group, Mesh, PlaneGeometry, Color, DirectionalLight, AmbientLight, PointLight,
  MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial
} from 'three/webgpu';
import { uv, uniform, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  const root = new Group();
  const tweens = [];
  const tickers = [];

  // ---- Backdrop gradient plane (staged, never void) ----
  const bgGeo = new PlaneGeometry(8, 7);
  const bgMat = new MeshBasicNodeMaterial({ transparent: false });
  bgMat.colorNode = mix(
    uniform(new Color('#0b0b10')),
    uniform(new Color('#14141a')),
    uv().y
  );
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---- Lighting (product-shot: key provided by scene, add rim + accent locally) ----
  const rim = new DirectionalLight(0xff2a38, 0.8);
  rim.position.set(-3.5, 0.8, 2.2);
  root.add(rim);

  const fill = new DirectionalLight(0xe8ecf2, 0.45);
  fill.position.set(3.2, -0.6, 2.0);
  root.add(fill);

  const amb = new AmbientLight(0x14141a, 0.55);
  root.add(amb);

  // accent glow point near focus position
  const accentGlow = new PointLight(0xff2a38, 0.7, 4.5, 2.0);
  accentGlow.position.set(0.0, 0.0, 1.2);
  root.add(accentGlow);

  // ---- Column group ----
  const column = new Group();
  root.add(column);

  // ---- Headline (pinned) ----
  const headline = ctx.fontAtlas.createText('Inside the atelier', {
    fontSize: 68, color: '#e8ecf2', align: 'left'
  });
  headline.position.set(-1.6, 1.9, 0);
  root.add(headline);

  // ---- Constants ----
  const PLATE_W = 1.9, PLATE_H = 1.2;
  const PITCH = 1.5;
  const NUM = 6;
  const LOOP = NUM * PITCH; // 9.0
  const HALF = LOOP / 2;
  const COLUMN_X = 0.9;

  const captions = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE'
  ];

  // Distinct crop regions (offsetX, offsetY, repeatX, repeatY) -> 6 distinct photographs
  const crops = [
    [0.00, 0.50, 0.50, 0.50],
    [0.50, 0.50, 0.50, 0.50],
    [0.00, 0.00, 0.50, 0.50],
    [0.50, 0.00, 0.50, 0.50],
    [0.25, 0.25, 0.50, 0.50],
    [0.00, 0.00, 1.00, 1.00]
  ];

  // ---- Build plates ----
  const plateGroups = [];
  const photoMaterials = [];
  const accentStrips = [];

  for (let i = 0; i < NUM; i++) {
    const pg = new Group();
    pg.position.x = COLUMN_X;
    pg.userData.baseY = i * PITCH;
    pg.userData.index = i;

    // Frame backing (machined ink bevel + brushed edge highlight)
    const frameGeo = new PlaneGeometry(PLATE_W + 0.06, PLATE_H + 0.06);
    const frameMat = new MeshPhysicalNodeMaterial({
      color: new Color('#16161d'),
      roughness: 0.5,
      metalness: 0.5,
      clearcoat: 0.25,
      clearcoatRoughness: 0.45
    });
    const frame = new Mesh(frameGeo, frameMat);
    frame.position.z = -0.02;
    pg.add(frame);

    // Photo plate
    const photoGeo = new PlaneGeometry(PLATE_W, PLATE_H);
    const photoMat = new MeshPhysicalNodeMaterial({
      color: new Color('#ffffff'),
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1,
      clearcoatRoughness: 0.5
    });
    const photo = new Mesh(photoGeo, photoMat);
    pg.add(photo);
    photoMaterials.push(photoMat);

    // Accent strip (left edge, emissive signal red)
    const stripGeo = new PlaneGeometry(0.03, PLATE_H + 0.06);
    const stripMat = new MeshStandardNodeMaterial({
      color: new Color('#ff2a38'),
      emissive: new Color('#ff2a38'),
      emissiveIntensity: 1.4,
      roughness: 0.4,
      metalness: 0.2
    });
    const strip = new Mesh(stripGeo, stripMat);
    strip.position.set(-(PLATE_W / 2 + 0.015), 0, 0.01);
    strip.visible = false;
    pg.add(strip);
    accentStrips.push(strip);

    column.add(pg);
    plateGroups.push(pg);
  }

  // ---- Captions (pinned at x=-1.6, cross-fade on focus) ----
  const captionGroup = new Group();
  captionGroup.position.set(-1.6, 0, 0.1);
  root.add(captionGroup);

  const captionObjs = [];
  const captionProxies = [];
  for (let i = 0; i < NUM; i++) {
    const cap = ctx.fontAtlas.createText(captions[i], {
      fontSize: 18, color: '#e8ecf2', align: 'left', letterSpacingPx: 1.44
    });
    cap.position.set(0, 0, 0);
    cap.visible = false;
    captionGroup.add(cap);
    captionObjs.push(cap);
    captionProxies.push({ o: 0 });

    // make materials transparent for fade
    cap.traverse(c => {
      if (c.material) {
        c.material.transparent = true;
        c.material.opacity = 0;
      }
    });
  }

  // ---- Texture load (async, cached) ----
  const texUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  ctx.textureLoader.loadTexture(texUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.needsUpdate = true;
    for (let i = 0; i < NUM; i++) {
      const c = crops[i];
      const ct = tex.clone();
      ct.offset.set(c[0], c[1]);
      ct.repeat.set(c[2], c[3]);
      ct.colorSpace = THREE.SRGBColorSpace;
      ct.needsUpdate = true;
      photoMaterials[i].map = ct;
      photoMaterials[i].needsUpdate = true;
    }
  }).catch(() => { /* texture optional */ });

  // ---- Scroll state + focus logic ----
  let targetScroll = 0;
  let currentScroll = 0;
  let focusedIndex = -1;

  const setCaptionOpacity = (idx, o) => {
    captionObjs[idx].traverse(c => {
      if (c.material) c.material.opacity = o;
    });
  };

  const update = () => {
    // weighted inertia toward target (damping 0.12)
    currentScroll += (targetScroll - currentScroll) * 0.12;

    let nearest = 0;
    let nearestDist = Infinity;
    for (let i = 0; i < NUM; i++) {
      const pg = plateGroups[i];
      let y = pg.userData.baseY + currentScroll;
      // wrap to [-HALF, HALF] (modulo LOOP)
      y = (((y + HALF) % LOOP) + LOOP) % LOOP - HALF;
      pg.position.y = y;
      const d = Math.abs(y);
      if (d < nearestDist) { nearestDist = d; nearest = i; }
    }

    if (nearest !== focusedIndex) {
      const prev = focusedIndex;
      focusedIndex = nearest;

      for (let i = 0; i < NUM; i++) {
        const pg = plateGroups[i];
        const isFocus = i === focusedIndex;
        tweens.push(gsap.to(pg.scale, {
          x: isFocus ? 1.06 : 1.0,
          y: isFocus ? 1.06 : 1.0,
          duration: 0.35,
          ease: 'power3.out'
        }));
        accentStrips[i].visible = isFocus;

        const cap = captionObjs[i];
        if (isFocus) {
          cap.visible = true;
          captionProxies[i].o = 0;
          setCaptionOpacity(i, 0);
          tweens.push(gsap.fromTo(cap.position, { y: -0.08 }, {
            y: 0, duration: 0.35, ease: 'power2.out'
          }));
          tweens.push(gsap.to(captionProxies[i], {
            o: 1, duration: 0.35, ease: 'power2.out',
            onUpdate: () => setCaptionOpacity(i, captionProxies[i].o)
          }));
        } else if (i === prev) {
          captionProxies[i].o = 1;
          tweens.push(gsap.to(captionProxies[i], {
            o: 0, duration: 0.2, ease: 'power2.in',
            onUpdate: () => setCaptionOpacity(i, captionProxies[i].o),
            onComplete: () => { cap.visible = false; }
          }));
        } else {
          cap.visible = false;
          captionProxies[i].o = 0;
          setCaptionOpacity(i, 0);
        }
      }
    }
  };

  gsap.ticker.add(update);
  tickers.push(update);

  // ---- Entrance animations ----
  for (let i = 0; i < NUM; i++) {
    tweens.push(gsap.from(plateGroups[i].position, {
      x: COLUMN_X + 0.4,
      duration: 0.6,
      delay: 0.1 + i * 0.08,
      ease: 'power3.out'
    }));
    tweens.push(gsap.from(plateGroups[i].scale, {
      x: 0.92, y: 0.92,
      duration: 0.7,
      delay: 0.1 + i * 0.08,
      ease: 'power4.out'
    }));
  }
  tweens.push(gsap.from(column.position, {
    y: 0.4, duration: 0.7, ease: 'power3.out'
  }));
  tweens.push(gsap.from(headline.position, {
    y: 2.3, duration: 0.7, delay: 0.15, ease: 'power2.out'
  }));

  // subtle idle breathing
  tweens.push(gsap.to(column.rotation, {
    z: 0.01, duration: 4.5, yoyo: true, repeat: -1, ease: 'sine.inOut'
  }));
  tweens.push(gsap.to(accentGlow, {
    intensity: 0.95, duration: 2.6, yoyo: true, repeat: -1, ease: 'sine.inOut'
  }));

  // ---- Cinematic primitive: fly-through on scroll ----
  let flyResult = null;
  try {
    flyResult = ctx.primitives['fly-through'](root, { depthUnits: 2.5 });
  } catch (e) { /* primitive optional */ }

  // ---- Event handlers ----
  root.userData.handlers = {
    scroll: (delta) => {
      targetScroll += (delta || 0) * 1.5;
    }
  };

  // ---- Cleanup ----
  root.userData.cleanup = () => {
    for (const t of tweens) t.kill();
    for (const tk of tickers) gsap.ticker.remove(tk);
    if (flyResult && flyResult.cleanup) flyResult.cleanup();
    root.traverse(c => {
      if (c.geometry) c.geometry.dispose();
      if (c.material) {
        const m = c.material;
        if (m.map) m.map.dispose();
        m.dispose();
      }
    });
  };

  return root;
}
